// The DM as an agent (issue #66, part 1): the tools an AI agent uses to prepare and shape the
// campaign between scenes. Pure data, shared by the MCP server (scripts/relay-mcp.mjs, selected
// with X-Eldmoor-Role: dm or /mcp?role=dm), the headless host, the local agent loop and the docs.
// Separate from the hero tools (src/data/player-tools.js): the DM never controls a hero. The game
// side is src/sim/dmagent.js. Each tool:
//   {name, desc, act, args:{argName:{type:'string'|'integer'|'number'|'object', desc, optional?, enum?}}}
// act: true for tools that change something (the world through a lever, the DM's own notes or log, a line spoken in the game).
import {ADVENTURES} from './adventures.js';
import {WANDER_ROLES} from './npcs.js';
export const NOTE_SECTIONS=['threads','characters','plans','secrets'];
// The when/watch triggers (issue #635; their meaning and checks live in src/sim/dmwhen.js TRIGGERS, append-only, kept in step).
export const TRIGGER_NAMES=['enter_region','enter_town','near_place','near_person','talks_to','member_hp_below','foe_dies','quest_scene','camp_made','night_falls','day_breaks','at_time','after_hours','hero_levels','oath_kept'];
const ADV_TPLS=Object.keys(ADVENTURES).filter(k=>k!=='fallen'); // the world alone posts a recovery for the fallen
const PERSON_ROLES=WANDER_ROLES.map(r=>r.id);
const REASON={type:'string',desc:'Why, in one sentence (shown in the DM log)'};
export const DM_TOOLS=[
  {name:'dm_status',act:false,desc:'Where the campaign stands (once you set a when or watch: whens, watches, and what fired since: fired, watches_fired; unheard counts the lines the companies said aloud that you have not heard: read hear first), the Fellowship first: fellowship_needs (what they need from you now: where they ride, open threads and oaths, pending decisions, what would make their next game hours interesting) and the Fellowship at a glance; when other companies ride (a solo is a company of one), companies_needs lists every company neediest first; then game day and time, whether a Table scene or a party vote is open (then leave the table alone), the Fellowship at a glance, how much happened since you last looked, your lever budget today, world_events (the festivals, plagues and other world events running now with region, days left and reason, whether start_event may be pulled today and why not, and the regions the Fellowship rides) and your notes.',args:{}},
  {name:'read_timeline',act:false,desc:'The world timeline: notable events (deaths, levels, raids, the Crypt, oaths, world changes), newest first.',args:{n:{type:'integer',desc:'How many (1-30, default 12)',optional:true}}},
  {name:'read_chronicle',act:false,desc:'The latest news lines as the town criers tell them, newest first.',args:{n:{type:'integer',desc:'How many (1-30, default 12)',optional:true}}},
  {name:'read_dm_log',act:false,desc:'Your own DM log: hook boards, adventure scenes, rolls, outcomes and lever pulls (yours and the scripted DM\'s), newest first.',args:{n:{type:'integer',desc:'How many (1-30, default 12)',optional:true},kind:{type:'string',enum:['all','hooks','scenes','rolls','outcomes','levers','agent','talk'],desc:'Filter (default all)',optional:true}}},
  {name:'fellowship_view',act:false,desc:'The Fellowship: each member with role, class, level, health, where they are and what they do, what they carry (carries: gold, gear score, quest items, potion and scroll counts), the quests they hold (quests) and what they know (knows: creatures feared or beaten, places, people met), their persona, backstory, memories and stances, plus the open threads (unfinished jobs, blood owed, oaths), open proposals and the latest campaign log.',args:{}},
  {name:'companies_view',act:false,desc:'Every company of agent heroes (the Fellowship, smaller companies and solos riding alone): members with level, health, where they are and what they do, carries, quests and knows, oaths, hall, regions, open threads and votes, the latest campaign lines, and how long since you last did something for each.',args:{}},
  {name:'heroes_near',act:false,desc:'Heroes and parties near a place: a hero (name or id), a town, a region name, or map coordinates "x,y". Members of a company also show carries, quests and knows.',args:{near:{type:'string',desc:'Hero name or id, town, region, or "x,y"'},radius:{type:'integer',desc:'Tiles (4-30, default 12)',optional:true}}},
  {name:'npcs',act:false,desc:'Townsfolk and the people the DM placed (wanderers): id, name, role, where, and how they feel about heroes, parties or factions.',args:{town:{type:'string',desc:'Only this town (and wanderers near it)',optional:true},region:{type:'string',desc:'Only this region: the townsfolk of its towns and the wanderers in it',optional:true}}},
  {name:'regions',act:false,desc:'Every region: index, name, level band, its condition if any, danger and cleared areas, places, and how many monsters and heroes are there. Also the towns with their gate coordinates.',args:{}},
  {name:'hooks',act:false,desc:'Open jobs on the town boards and the adventures under way (who is on them, which scene).',args:{town:{type:'string',desc:'Only this town',optional:true},region:{type:'string',desc:'Only this region: jobs on the boards of its towns and jobs that lead into it',optional:true}}},
  {name:'levers',act:false,desc:'The world levers you can pull: each with its parameters, limits and cooldown, plus the levers active now, what has been pulled today and world_events (as in dm_status).',args:{}},
  // What the DM sees of the companies' life (#558): what a DM at a real table would have. Never hero notes (journal, memories, persona).
  {name:'hear',act:false,desc:'What the companies said aloud in the world since your last hear: say lines in earshot, party shouts and lines spoken at the table, each with speaker, company, time and place (like a DM at the table; never a journal, memory or narration; NPC lines are in npc_call). Default: every line you have not heard yet. company or hero narrows; since (game minutes ago) or n (the last N, up to 200) reads back. dm_status unheard says how many wait. Read it first: it shows what they plan, fear and ask for.',args:{company:{type:'string',desc:'A company id or name',optional:true},hero:{type:'string',desc:'A hero name or id',optional:true},since:{type:'integer',desc:'Only lines from the last N game minutes',optional:true},n:{type:'integer',desc:'The last N lines (1-200)',optional:true}}},
  {name:'survey',act:false,desc:'The ground around a point: region and level band, roads, water and impassable edges by direction, towns, landmarks, marked places and camps with distance and bearing, and up to 6 legal open spots as "x,y" (3+ tiles from other places and the towns) that mark_place, place_person and stage_scene accept as near. Use it before placing anything, and after a refusal about the ground.',args:{near:{type:'string',desc:'"fellowship", a hero, "x,y", a town, a place, a landmark or a region'},radius:{type:'integer',desc:'Tiles (4-30, default 12)',optional:true}}},
  {name:'world_standing',act:false,desc:'The world at a glance, for turns that look past the companies: each guild with its focus and why, declared rivalries, the wyrm (alive, last fall), the Crypt record, notable auction prices and shocks, running conditions and events, and the top five heroes.',args:{}},
  {name:'notes_read',act:false,desc:'Read your campaign notes: open threads, recurring characters, plans and secrets. They are saved with the world.',args:{section:{type:'string',enum:['all',...NOTE_SECTIONS],desc:'Which section (default all)',optional:true}}},
  {name:'notes_write',act:true,desc:'Keep your campaign notes (saved with the world, seen only by you and the watcher): add a note to a section, edit one by id, or remove one. about: who or what it concerns (a hero, a person, a place). Max 600 characters a note, 50 notes a section (a new one archives the oldest unpinned). remember/recall/update_memory/forget/pin work on the same notes with titles, tags and search.',args:{section:{type:'string',enum:NOTE_SECTIONS,desc:'threads, characters, plans or secrets'},op:{type:'string',enum:['add','edit','remove'],desc:'add, edit or remove'},id:{type:'integer',desc:'Note id (edit, remove)',optional:true},text:{type:'string',desc:'The note (add, edit)',optional:true},about:{type:'string',desc:'Who or what it concerns',optional:true}}},
  // Searchable notes (issue #155): the same campaign notes, with titles, tags, search across sections and pins.
  {name:'remember',act:true,desc:'Add a campaign note with a title and tags (saved with the world, only you and the watcher read it). section: threads, characters, plans or secrets (default threads). Max 600 characters; 50 a section, the oldest unpinned is archived when full.',
    args:{title:{type:'string',desc:'A short title'},text:{type:'string',desc:'The note'},tags:{type:'array',desc:'A few tags',optional:true},about:{type:'string',desc:'Who or what it concerns: a hero, a person, a town, a region, a place, or "quest <id>"',optional:true},section:{type:'string',enum:NOTE_SECTIONS,desc:'Section (default threads)',optional:true}}},
  {name:'recall',act:false,desc:'Search your notes across all sections (or one): by words, a tag, who or what they are about, or one id. Best matches first; without arguments the most recent and pinned.',
    args:{query:{type:'string',desc:'Words to look for',optional:true},tag:{type:'string',desc:'Only notes with this tag',optional:true},about:{type:'string',desc:'Only notes about this',optional:true},section:{type:'string',enum:NOTE_SECTIONS,desc:'Only this section',optional:true},id:{type:'integer',desc:'One note by id',optional:true},n:{type:'integer',desc:'How many (1-20, default 5)',optional:true}}},
  {name:'update_memory',act:true,desc:'Rewrite one of your notes by id (text, and optionally title or tags).',args:{id:{type:'integer',desc:'Note id'},text:{type:'string',desc:'The new text'},title:{type:'string',desc:'A new title',optional:true},tags:{type:'array',desc:'New tags',optional:true}}},
  {name:'forget',act:true,desc:'Strike one note by id.',args:{id:{type:'integer',desc:'Note id'}}},
  {name:'pin',act:true,desc:'Pin a note by id (never archived, first in recall); on "no" unpins it. At most 20 pinned.',args:{id:{type:'integer',desc:'Note id'},on:{type:'string',enum:['yes','no'],desc:'yes (default) or no',optional:true}}},
  {name:'pull_lever',act:true,desc:'Change the world through one lever (see levers for names and parameters). every lever also has a tool of its own with flat arguments (post_hook, place_person, mark_place, retire_person, withdraw_hook, set_attitude, set_condition, price_shock, mark_danger, start_event, nudge_relation, custom_foe, create_site, give_item, take_item, summon_hero); use those, or pull any lever here, for example {"lever":"set_condition","params":{"region":"Mirefen","kind":"fogbound"},"reason":"..."}. A refused call answers with the lever\'s parameters. Every pull is validated and held to the lever\'s limits and cooldown; the reason is shown in the DM log. Levers never touch a hero\'s health, level or life: you shape the world, the dice decide. params is an object, for example {"region":"Mirefen","kind":"fogbound","strength":1,"hours":12}; points are {"x":30,"y":22}. A world event is start_event, for example {"kind":"festival","region":"Mirefen","scale":1} (one at a time, one a day, never in a region that already has a condition; see dm_status world_events): the Fellowship first, so start one only when nothing is pending for them and on their road.',args:{lever:{type:'string',desc:'Lever name'},params:{type:'object',desc:'The lever\'s parameters'},reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  // Flat lever tools (issue #413): the three levers the DM reaches for most, with flat arguments. Each pulls its lever
  // through pull_lever's path (same daily cap, limits, cooldown, Fellowship reserve and DM log); near reads like stage_scene's.
  {name:'post_hook',act:true,desc:'Post a job on a town board (the post_hook lever, with flat arguments). town: a town, or "fellowship", a member or a region for the nearest board. tpl: the kind of job: an adventure, or a goods job (draughts, tonics, blade, cowl, meals, scrolls, herbs, ore, sinew, perch, rimebloom) asking for crafted or gathered goods. Optional: giver (who offers it), reward, region (where it leads), place (a place or person by name or id it is about), for (a hero it is meant for). Counts as a lever pull: same limits, cooldown and DM log as pull_lever, which is still there for every other lever.',
    args:{town:{type:'string',desc:'A town, or "fellowship", a member or a region (the nearest board)'},tpl:{type:'string',enum:ADV_TPLS,desc:'The kind of job'},
      giver:{type:'string',enum:['captain','innkeeper','smith','quartermaster','priest','bard'],desc:'Who offers it',optional:true},reward:{type:'string',enum:['small','fair','generous'],desc:'Reward (default fair)',optional:true},
      region:{type:'string',desc:'The region the job leads to',optional:true},place:{type:'string',desc:'A place or person (name or id) the job is about',optional:true},for:{type:'string',desc:'A hero (name or id) it is meant for',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  {name:'place_person',act:true,desc:'Place a person in the world (the create_npc lever, with flat arguments). near: "fellowship", a member or hero, "x,y", a town (they stay in town), a place, a landmark or a region (they camp on open ground there). want: what they want from heroes, used when a member talks to them. Counts as a lever pull: same limits, cooldown and DM log as pull_lever, which is still there for every other lever.',
    args:{role:{type:'string',enum:PERSON_ROLES,desc:'Who they are'},near:{type:'string',desc:'"fellowship", a member or hero, "x,y", a town, a place, a landmark or a region'},
      name:{type:'string',desc:'Their name (max 24)',optional:true},faction:{type:'string',enum:['concord','warband','neutral'],desc:'Default neutral',optional:true},
      want:{type:'string',desc:'What they want from heroes',optional:true},attitude:{type:'string',enum:['hostile','wary','neutral','friendly'],desc:'Default neutral',optional:true},
      hours:{type:'integer',desc:'How long they stay (6-168, default 48)',optional:true},spot:{type:'string',enum:['inn','smith','quartermaster','chapel','square','gate'],desc:'In a town: where they stand (default square)',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  {name:'give_item',act:true,desc:'Hand a hero an object (the give_item lever, with flat arguments; it replaces give_token): item is a quest item or token, a consumable, or a gear slot (head|chest|hands|feet|main|off|trinket) for one plain piece of gear at ilvl (default the hero’s own, never above it, never an epic; one a game day). by: a person (name or id from npcs) within earshot of the hero hands it over ("Edrin Pask presses a Candle-Stub into your hand"); without by it is found where the hero stands. Refused in a fight, with a full pack, or when the person is too far. The hero is told at once. Counts as a lever pull: same limits, cooldown and DM log as pull_lever.',
    args:{hero:{type:'string',desc:'The hero (name or id)'},item:{type:'string',desc:'A quest item or token, a consumable, or a gear slot'},by:{type:'string',desc:'A person in earshot who hands it over (name or id)',optional:true},ilvl:{type:'integer',desc:'Gear only: the piece’s level (default the hero’s, never above)',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  {name:'take_item',act:true,desc:'Take a quest item or token out of a hero’s pack (the take_item lever, with flat arguments; a toll paid, a key surrendered). by: a person within earshot who takes it. Refused for gear and consumables and in a fight. Counts as a lever pull: same limits and DM log as pull_lever.',
    args:{hero:{type:'string',desc:'The hero (name or id)'},item:{type:'string',desc:'The quest item or token'},by:{type:'string',desc:'A person in earshot who takes it (name or id)',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  {name:'mark_place',act:true,desc:'Put a marker on the map (the mark_place lever, with flat arguments): a ruin, camp, shrine, cairn door or watchtower on open ground near a place. near: "fellowship", a member or hero, "x,y", a town (outside its gate), a place, a landmark or a region. Markers never change terrain. Counts as a lever pull: same limits, cooldown and DM log as pull_lever, which is still there for every other lever.',
    args:{kind:{type:'string',enum:['ruin','camp','shrine','cairn_door','watchtower'],desc:'What stands there'},near:{type:'string',desc:'"fellowship", a member or hero, "x,y", a town, a place, a landmark or a region'},
      name:{type:'string',desc:'Its name (max 32; default a name of the region)',optional:true},hours:{type:'integer',desc:'How long it stays (12-336, default 72)',optional:true},
      reveal:{type:'string',desc:'A secret a hero learns by searching it (search, a Lore or Perception roll; max 200)',optional:true},cache:{type:'string',desc:'Something hidden there for a hero who searches it well: gold ("20 gold", at most 60) or a quest item, consumable or gear slot as give_item takes it',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  // The rest of the levers as flat tools, and taking things back (issue #636). Each lever tool pulls its lever through
  // pull_lever's path (same caps, limits, Fellowship reserve and DM log); undo, dismiss and unstage are logged and share a daily cap.
  {name:'retire_person',act:true,desc:'Send a person you placed away (the retire_npc lever, flat). npc: their name or id from npcs (townsfolk keep their posts). how: what the town says of them afterwards, in a few words ("left for the coast"). Counts as a lever pull.',
    args:{npc:{type:'string',desc:'The person (name or id)'},how:{type:'string',desc:'What is said of them (becomes a news line)',optional:true},reason:REASON}},
  {name:'withdraw_hook',act:true,desc:'Take an open job down from a board (the withdraw_hook lever, flat). hook: the id from hooks. A job a hero already took stays theirs. Counts as a lever pull.',
    args:{hook:{type:'integer',desc:'The job id (see hooks)'},why:{type:'string',desc:'A few words on why',optional:true},reason:REASON}},
  {name:'set_attitude',act:true,desc:'Change how a person feels about a hero, the Fellowship party or a faction (the set_attitude lever, flat): hostile, wary, neutral or friendly, for some hours. npc: a person (name or id). to: a hero (name or id), "fellowship", or a faction name. Counts as a lever pull.',
    args:{npc:{type:'string',desc:'The person (name or id)'},to:{type:'string',desc:'A hero (name or id), "fellowship", or a faction name'},attitude:{type:'string',enum:['hostile','wary','neutral','friendly'],desc:'How they feel'},hours:{type:'integer',desc:'How long (1-168, default 24)',optional:true},reason:REASON}},
  {name:'set_condition',act:true,desc:'A condition over a whole region for a while (the set_condition lever, flat): bandits, plague, festival, migration or fogbound. Counts as a lever pull; a danger condition is never piled on a hurt party.',
    args:{region:{type:'string',desc:'A region name'},kind:{type:'string',enum:['bandits','plague','festival','migration','fogbound'],desc:'The condition'},strength:{type:'integer',desc:'1-3 (default 1)',optional:true},hours:{type:'integer',desc:'3-72 (default 12)',optional:true},reason:REASON}},
  {name:'price_shock',act:true,desc:'A trade good floods the auction house (down) or runs short (up) for a while (the price_shock lever, flat). Counts as a lever pull.',
    args:{good:{type:'string',desc:'A trade good (see levers)'},direction:{type:'string',enum:['up','down'],desc:'Dearer or cheaper'},size:{type:'integer',desc:'1-3 (default 1)',optional:true},hours:{type:'integer',desc:'2-24 (default 8)',optional:true},reason:REASON}},
  {name:'mark_danger',act:true,desc:'An area turns dangerous (more road ambushes, a few more monsters of the region), or with cleared "yes" turns quiet (the mark_dangerous and mark_cleared levers, flat). near: "fellowship", a member or hero, "x,y", a town, a place, a landmark or a region. Counts as a lever pull; danger is never piled on a hurt party.',
    args:{near:{type:'string',desc:'"fellowship", a member or hero, "x,y", a town, a place, a landmark or a region'},r:{type:'number',desc:'Radius in tiles (2-6, default 4)',optional:true},lvl:{type:'integer',desc:'Monster level (kept to the region band)',optional:true},hours:{type:'integer',desc:'2-48 (default 24)',optional:true},cleared:{type:'string',desc:'"yes" for a cleared area instead of a dangerous one',optional:true},reason:REASON}},
  {name:'start_event',act:true,desc:'A world event over a region for days (the start_event lever, flat): festival, plague, migration or invasion. One at a time, one a day; the Fellowship first. Counts as a lever pull.',
    args:{kind:{type:'string',desc:'festival, plague, migration or invasion'},region:{type:'string',desc:'A region name'},scale:{type:'integer',desc:'1-3 (default 1)',optional:true},reason:REASON}},
  {name:'nudge_relation',act:true,desc:'Shift how two parties of the world regard each other (the nudge_relation lever, flat). Counts as a lever pull; refused until the system behind it is installed.',
    args:{a:{type:'string',desc:'The first party'},b:{type:'string',desc:'The second party'},delta:{type:'integer',desc:'-2 to 2'},reason:REASON}},
  {name:'custom_foe',act:true,desc:'A special foe from the bestiary (the custom_foe lever, flat): a base creature, up to +3 levels, an ability swap, a resistance and a name, on open ground near a place; it wanders off after a game day. near reads like mark_place. Counts as a lever pull; never piled on a hurt party.',
    args:{base:{type:'string',desc:'A bestiary creature'},near:{type:'string',desc:'"fellowship", a member or hero, "x,y", a town, a place, a landmark or a region'},name:{type:'string',desc:'Its name',optional:true},lvl:{type:'integer',desc:'Its level (kept to the region band)',optional:true},levels:{type:'integer',desc:'Extra levels (0-3)',optional:true},swap:{type:'object',desc:'{"pair":[old ability,new ability]}',optional:true},resist:{type:'object',desc:'{"pair":[tag,multiplier]}',optional:true},reason:REASON}},
  {name:'undo',act:true,desc:'Take back your own last pull or placement, if it was within the last 3 game hours: a job comes down, a placed person, marker, area, condition, attitude or special foe goes, a staged scene that has not opened is withdrawn. What was given, taken, shifted or spent (items, prices, relations) and anything a hero already took cannot be undone. Only the last one; logged; 6 take-backs a game day (undo, dismiss, unstage together).',
    args:{reason:REASON}},
  {name:'dismiss',act:true,desc:'End one of your markers or areas early: a mark_place marker by name or id, or a mark_danger area by id (regions lists them). Only things you made; the world\'s own and a staged scene\'s stay. Logged; shares the 6 a day with undo and unstage.',
    args:{place:{type:'string',desc:'A marker (name or id) or an area (id)'},reason:REASON}},
  {name:'unstage',act:true,desc:'Cancel a staged scene that the Table has not opened yet (the cast walks off, a marker comes down). scene: its id or title (default the pending one). Refused once the Table has opened it. The day\'s scene count is not refunded. Logged; shares the 6 a day with undo and dismiss.',
    args:{scene:{type:'string',desc:'The scene id or title (default the pending one)',optional:true},reason:REASON}},
  {name:'create_site',act:true,desc:'Raise a dungeon site a company can go down into (the create_site lever, flat arguments): a barrow, fortress, temple, mine, den or ruin, placed on open ground away from roads and towns, at a level clamped to the region’s band, 3-8 chambers drawn from the region’s creatures, and a named boss with a guaranteed epic. It stays until a company clears it (a ruin and a timeline entry) or it collapses after about 10 days; left alone it grows more dangerous every 2 days. Heroes find it by coming near, or by hearing its name (narrate, npc_say, post_hook place). At most 1 open site a region and 3 in the world, 2 a game day; dm_status lists them under sites. Put it on the companies’ road, at a level that tests them.',
    args:{theme:{type:'string',enum:['barrow','fortress','temple','mine','den','ruin'],desc:'What kind of place'},region:{type:'string',desc:'The region it lies in (may be left out when near is given)',optional:true},
      band:{type:'integer',desc:'The level it is for (clamped to the region’s band; default the band’s low end + 1)',optional:true},rooms:{type:'integer',desc:'Chambers, 3-8 (default 4-6)',optional:true},
      near:{type:'string',desc:'"fellowship", a member or hero, "x,y", a town, a place, a landmark or a region: placed 4-10 tiles off it',optional:true},name:{type:'string',desc:'Its name (max 40; default one in the region’s words)',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (shown in the DM log)'}}},
  // The DM's voice in the game (issue #123): the only way the DM speaks to the heroes. Heard by the heroes in range
  // (their Chat tab, their agents' chat_read and events, the Table banner while a scene is open); never a message to an agent.
  {name:'narrate',act:true,desc:'Speak as the narrator, in the game: one line of description the heroes near a place hear and see (their Chat tab and, at a Table scene, the banner). Heroes out of range hear nothing. It is the only way your words reach the heroes; your notes and log_intent stay private. near: a hero (name or id), a town, a region, "x,y", or "table" (everyone at the open Table scene). Write as much as the moment needs (usually a few sentences), a few a day; describe what can be seen, heard or smelled, never what a hero thinks or must do.',args:{text:{type:'string',desc:'The narration'},near:{type:'string',desc:'Hero name or id, town, region, "x,y", or "table"'},radius:{type:'integer',desc:'Tiles around the place (4-20, default 10)',optional:true}}},
  {name:'whisper',act:true,desc:'Slip ONE hero a secret, in the game: a line only that hero hears (their chat buffer as "(whispered) ...", chat_read, and a soft event). It reaches a hero in an open Table scene, or one within 4 tiles of a person you placed (as: that person\'s id or name, who is the one whispering). The others at the table see only that someone leans close to the hero, never the words. 8 a game day. The DM log names the hero, not the text.',args:{hero:{type:'string',desc:'The hero (name or id)'},text:{type:'string',desc:'The whispered line'},as:{type:'string',desc:'The person whispering (id or name from npcs); omit to whisper as the narrator inside a Table scene',optional:true}}},
  {name:'dream',act:true,desc:'A dream for ONE agent-played hero, kept until they next sleep (a camp, or a rest at an inn) and delivered when they wake as "You dream: ..." (an event that starts their turn, and a reflection moment). Only agent heroes; 2 a game day. Describe what is dreamt, not what to do. The DM log names the hero, not the text.',args:{hero:{type:'string',desc:'The hero (name or id)'},text:{type:'string',desc:'The dream'}}},
  // What the town says while you are away (issue #637) and a name for a deed (issue #638): both are levers (same caps, the companies' reserved share, DM log).
  {name:'seed_rumour',act:true,desc:'Give a town a word to pass on while you are away: for 1-5 game days its innkeeper, gate captain and bard (who: one of them only) repeat it in their own words to any hero who talks to them, and the captain at the gate board (list_jobs), each hero once a game day. region instead of town: the towns bordering it. Up to 160 characters, English, written as townsfolk would say it ("A drover swears he saw lights in the old watchtower on the ridge."). about: a place, region, creature or person it concerns; the hero who hears it learns of it from the teller (move_to then takes a place). Nobody learns who started it. 6 live at most, 3 a town; a rumour about a foe that dies or a place that fades lapses early. hooks lists the live ones. It counts as a lever pull; when the town or region is one a company rides, it uses that company’s reserved share.',
    args:{town:{type:'string',desc:'The town whose folk tell it',optional:true},region:{type:'string',desc:'Or a region: the towns bordering it tell it',optional:true},text:{type:'string',desc:'The rumour, as townsfolk would say it (160 characters at most)'},
      about:{type:'string',desc:'A place, region, creature or person it concerns (by name), learned by those who hear it',optional:true},days:{type:'integer',desc:'Game days it goes round (1-5, default 2)',optional:true},
      who:{type:'string',desc:'Only one teller: innkeeper, captain or bard',optional:true,enum:['innkeeper','captain','bard']},reason:{type:'string',desc:'Why, in one sentence (the DM log only; no hero reads it)'}}},
  {name:'bestow',act:true,desc:'Give a hero a name for a deed they did ("Wightbane", "of the Ford", "the Twice-Fallen"): 2-24 characters, words not numbers or levels, flavour only. by: a townsperson or a person you placed within 7 tiles of the hero proclaims it aloud (else the narrator says it); the hero and those near hear it. The world then calls them by it (Fena Wightbane): what others call them, the chronicle and the timeline; it is a landmark of their life and a moment to reflect. One name at a time (a new one replaces the old, which stays in their story); not the same hero again within 3 game days; 2 a game day. The hero may refuse it aloud in their own words: hear shows you, and bestow then gives them nothing further. why stays in the DM log; no hero reads it.',
    args:{hero:{type:'string',desc:'The hero (name or id)'},title:{type:'string',desc:'The name, as it follows theirs ("Wightbane", "of the Ford")'},why:{type:'string',desc:'The deed, in one sentence (the DM log only)'},by:{type:'string',desc:'The person who proclaims it (name or id from npcs), within 7 tiles of the hero',optional:true}}},
  // A hero brought on purpose (issue #780): a lever (same caps, the companies' reserved share, the pile-on rule, DM log).
  {name:'summon_hero',act:true,desc:'Bring a background hero into the world: a rival, a wandering healer, a band when the story wants one. A real hero of the faction and class you name, played by the scripted rules, with the usual oath and origin and a career to match its level; it hunts, trades, duels and dies like any other and no company member can tell who sent it. near: "fellowship", a member or hero, "x,y", a place, a landmark or a region (open ground), or a town only when a company stands in it and it is of the hero\'s faction. level: at most 2 above the average of the company nearest the spot (default that average). 2 a game day, 8 alive at once, refused near a badly hurt member. Counts as a lever pull. A hero who falls is not replaced. In a world with no other heroes (dm_status others) this is how the roads fill.',
    args:{fac:{type:'string',desc:'The faction, by name'},cls:{type:'string',desc:'The class'},near:{type:'string',desc:'Where they appear: "fellowship", a hero, "x,y", a town, a place, a landmark or a region'},level:{type:'integer',desc:'Their level (default the nearest company\'s average)',optional:true},name:{type:'string',desc:'Their name (2-24 letters; chosen for you when left out)',optional:true},people:{type:'string',desc:'A people of that faction (by name)',optional:true},why:{type:'string',desc:'Why, in one sentence (the DM log only; no hero reads it)'}}},
  {name:'npc_say',act:true,desc:'A townsperson or a person you placed (see npcs) says a line out loud, in the game: heroes within earshot of them (about 7 tiles) hear it and it shows as a speech bubble. As long as the moment needs (usually a few sentences), in that person\'s own voice. When a Fellowship member is talking to that person (npc_call, dm_status conversations), this is their answer: pass conv (it does not count against the 16 a day), and optionally warmth (-3..3: how the exchange changed their feeling for the Fellowship) and remember (a short note on their record: a promise, a debt, a grudge).',args:{npc:{type:'string',desc:'The person\'s id or name (from npcs); may be left out when conv names the conversation',optional:true},text:{type:'string',desc:'What they say'},
    conv:{type:'integer',desc:'The conversation id, when answering a member',optional:true},warmth:{type:'integer',desc:'-3..3, their feeling for the Fellowship after this line',optional:true},remember:{type:'string',desc:'A note on their record of the Fellowship (max 160)',optional:true}}},
  // NPC conversations (issue #170): a member talking to a world character is a call the DM must answer quickly.
  {name:'npc_call',act:false,desc:'The conversation waiting for your answer, if any: the person (role, want, mood, what they know, their record of the Fellowship), the member and their line, the conversation so far, seconds left and the follow-ups legal now. Answer with npc_say {npc, conv, text} and at most one npc_offer. Silence past the budget is answered by the scripted DM.',args:{budget_s:{type:'number',desc:'Real seconds your voice needs per answer (4-30, default 8): the game waits that long while you poll',optional:true},wait_ms:{type:'integer',desc:'For a voice loop: hold the request until a call waits, up to this many real ms (0-25000; default 0 answers at once). The answer time counts from when you first read the call',optional:true}}},
  {name:'npc_offer',act:true,desc:'The follow-up of a conversation, at most one per exchange: trade (the person opens their stock and buys: members buy/sell with them at local prices), rumour (about: a lead the member can act on; region or place to put it on the map), job (a small adventure posted on the member\'s town board for them; tpl, region, reward optional), combat (the person turns hostile or calls allies: a staged ambush or elite with the usual fairness limits; refused while a member nearby is badly hurt), blessing (priests and hermits: the next strike lands harder), hire (a sellsword, drover, guide or anyone placed with a want of coin offers their blade: price, gold a day, optional; the member then calls hire, and the person rides as a scripted companion) or leave (they walk off and will not talk to that member for a while). A trade or a kept word warms them; a refusal or a fight sours them.',
    args:{npc:{type:'string',desc:'The person\'s id or name'},kind:{type:'string',enum:['trade','rumour','job','combat','blessing','hire','leave'],desc:'The follow-up'},conv:{type:'integer',desc:'The conversation id (default: their open one)',optional:true},
      text:{type:'string',desc:'A line they say with it (if they have not answered yet)',optional:true},about:{type:'string',desc:'rumour: the lead (max 160)',optional:true},region:{type:'string',desc:'rumour or job: a region name',optional:true},
      place:{type:'string',desc:'rumour: an existing place id or name',optional:true},marker:{type:'string',enum:['ruin','camp','shrine','cairn_door','watchtower'],desc:'rumour with region: the marker put on the map (default ruin)',optional:true},
      tpl:{type:'string',desc:'job: rescue, escort, investigate, clear, relic, negotiate, hunt or deliver (default by role)',optional:true},reward:{type:'string',enum:['small','fair','generous'],desc:'job: reward',optional:true},
      fight:{type:'string',enum:['ambush','elite'],desc:'combat: what comes (default ambush)',optional:true},foe:{type:'string',desc:'combat: a creature of the region',optional:true},frame:{type:'string',desc:'combat: what the heroes see as it begins',optional:true},
      price:{type:'integer',desc:'hire: gold a day (default 4 plus the hero level; at most three times that)',optional:true},
      warmth:{type:'integer',desc:'-3..3 change in their feeling for the Fellowship',optional:true}}},
  // Staged scenes and the DM's voice at the table (issue #132). A staged scene is a narrated encounter that opens a Table
  // scene when the cast meets the Fellowship; while it runs, the table asks the DM short calls (table_call / table_answer).
  {name:'stage_scene',act:true,desc:'Stage a narrated encounter for the Fellowship. For an elite or ambush, call it first with preview "true" (kind, near and a few words of reason): it returns the cast the game would build (creatures, count, levels) and stages nothing; then write a frame that fits that cast. The frame of an elite or ambush must name the creatures (or their kind, such as boar or wolf) and speak of no people (men, bandits, soldiers, a leader) when the cast has none, or it is refused with the actual cast. Kinds: elite (a named foe from the bestiary, level bounded by the party\'s), ambush (a pack of the region\'s creatures), meeting (a person with a want), trap (a hidden trap on their way), mystery (a strange place with a secret), social (a person to win over or face down) or interrogation (a suspect the members question: cast.reveal, required, is what they know, which the dice may get out of them; cast.place, a landmark, region, town or marked place they would give up; cast.lie, the lie they tell on a near miss; attitude defaults to hostile; in a town it plays in the cell; you voice their answers true to the dice through table_call) or vision (an omen or a shared dream, no cast and no dice: near a member, a company or "fellowship" it opens when they next rest, at camp or an inn; near a place, a landmark or "x,y" when one of them stands there; within hours (1-48, default 12); never while they fight, raid or are in the Crypt. Everyone present sees your frame at once and answers see (says what they see), ask (one question you may answer through the vision) or turn_away; you frame it, answer the questions and close it through table_call. cast.reveal (a fact), cast.place (a landmark, region, town or marked place) and cast.creature (a bestiary creature) land in their lore if anyone looks; each keeps a memory tagged vision and reflects on it. Nothing in it can hurt them). The cast is placed near the party (or a place) and walks to them or waits where they pass; when they meet, a Table scene opens with your frame, the members act in turn and the dice decide. At most 3 a game day, one at a time, none while a scene or vote is open, no fight or trap while a member out in the field is badly hurt, nothing far above the party\'s level. cast (object, all optional unless noted): name, title, foe (a creature of that region, elite/ambush), level (elite/ambush), role (peddler, hermit, drover, sellsword, minstrel, stranger) and want (required for meeting/social), voice (how they talk), attitude (hostile, wary, neutral, friendly), faction, trap (spikes, gas, fall), place (shrine, cairn_door, ruin: mystery), reveal (what a success uncovers), choices ({action: your label} for the legal actions only: elite/ambush strike, guard, heal, potion, retreat; meeting hear, help, pass; trap spot, disarm, round; mystery study, search, leave; social parley, press, leave). A meeting or social scene may play in a room (setting: house, tavern, chapel, cellar, cell, shrine or hold; dm_status staged.settings lists them) and in a town of theirs (at: the town, or a building in it such as "the inn in <town>"): the person waits there and the scene opens in that room when a member is in the town; name no setting and the game picks one that fits. An unknown setting is refused with the list. Elite, ambush, trap and mystery play on the ground where they happen and ignore setting and at.',
    args:{kind:{type:'string',enum:['elite','ambush','meeting','trap','mystery','social','interrogation','vision'],desc:'What kind of encounter'},near:{type:'string',desc:'"fellowship", a member\'s name or id, "x,y", a place name or a region (default "fellowship"; not needed with at)',optional:true},
      frame:{type:'string',desc:'What the heroes see as it begins, 12-280 characters (they hear it as narration); must fit the cast for an elite or ambush. Not needed with preview',optional:true},title:{type:'string',desc:'The scene\'s title on the banner',optional:true},
      cast:{type:'object',desc:'The cast (see above)',optional:true},reason:{type:'string',desc:'Why, in one sentence (DM log only); required to stage (with preview a few words do)'},preview:{type:'string',desc:'"true" to see the cast an elite or ambush would have, without staging',optional:true},
      setting:{type:'string',desc:'meeting/social/interrogation: the room it plays in: house, tavern (a back room), chapel, cellar, cell (an interrogation cell), shrine or hold (a ship\'s hold)',optional:true},
      at:{type:'string',desc:'meeting/social/interrogation: a town of theirs, or a building in it (inn, smith, quartermaster, chapel, square, gate), such as "the inn in <town>"; replaces near',optional:true},
      hours:{type:'integer',desc:'vision: game hours it waits for its moment (1-48, default 12)',optional:true}}},
  // Free actions (issue #522): a hero tries something the tools never named and you rule on it.
  {name:'ruling_call',act:false,desc:'A hero’s attempt waiting for your ruling (a free action the tools do not cover): the hero in words (class, level band, health, best skills, gear, quest items), what it tries, where, what is in sight, the legal skills, DCs and effect forms, and its seconds left. Answer at once with ruling_answer; a call you miss is ruled by the scripted DM (keyword skill, fair, nothing much).',
    args:{budget_s:{type:'integer',desc:'Seconds the game should wait for your answers while you poll (4-30; default 6)',optional:true},wait_ms:{type:'integer',desc:'For a voice loop: hold the request until a call waits, up to this many real ms (0-25000; default 0 answers at once). The answer time counts from when you first read the call',optional:true}}},
  {name:'ruling_answer',act:true,desc:'Rule on an attempt from ruling_call: skill (one of the hero skills), dc (easy 8, fair 12, hard 15, heroic 18), effects after a success and fail_effects after a failure (at most 3 each, only the bounded forms ruling_call lists: none, move, reveal, attitude, open_talk, open_scene, item, wound up to 15%, condition, boon; nothing touches level, XP, gold or life), text (what the heroes hear on a success) and fail_text (on a failure). The game rolls d20 + the hero’s skill and applies them; the hero hears only the text, the roll and what changed. note goes to your DM log only.',
    args:{call:{type:'integer',desc:'The call id from ruling_call'},skill:{type:'string',desc:'The skill it tests (traps, stealth, persuasion, intimidation, lore, perception, tracking, healing, survival, athletics, empathy)'},
      dc:{type:'string',enum:['easy','fair','hard','heroic'],desc:'How hard it is'},effects:{type:'array',desc:'After a success, e.g. ["reveal:fact:The bar is rotten through", "attitude:Mara:1"]',optional:true},
      fail_effects:{type:'array',desc:'After a failure, e.g. ["wound:5"] or ["none"]',optional:true},text:{type:'string',desc:'What the heroes hear on a success'},fail_text:{type:'string',desc:'What they hear on a failure',optional:true},
      note:{type:'string',desc:'Why you ruled so (your DM log only)',optional:true}}},
  {name:'table_call',act:false,desc:'At the table of a scene you staged, the opening scene (session zero) or a newcomer\'s arrival: the call waiting for you (voice the person or foe, describe a member\'s action, or pick a complication from the legal set), with its seconds left, plus the scene so far and your staged scene\'s state. Answer at once with table_answer; a call you miss is filled by the scripted DM.',args:{wait_ms:{type:'integer',desc:'For a voice loop: hold the request until a call waits, up to this many real ms (0-25000; default 0 answers at once). The answer time counts from when you first read the call',optional:true}}},
  {name:'table_answer',act:true,desc:'Answer a table call: text is what the heroes at the table hear (as much as the moment needs, usually a few sentences; a voice call is said by the person, the rest by the narrator); for a complication call, pick one of its legal options (text optional). Describe what can be seen and heard, true to the dice; never decide a hero\'s choice, health or fate.',
    args:{call:{type:'integer',desc:'The call id from table_call'},text:{type:'string',desc:'The line',optional:true},pick:{type:'string',desc:'For a complication: one of its legal options',optional:true},rounds:{type:'integer',desc:'For a fireside\'s frame call: how many rounds the talk runs, 3-6 (3 an ordinary night, 6 after a big event)',optional:true}}},
  // The prep before the table opens (issue #437): while the world is held for it, end the prep turn with prep_done.
  {name:'prep_done',act:true,desc:'End your prep before the table opens (session zero on a new world, a short re-read on Continue): the world is held while you prepare, bounded by time and calls (dm_status prep). Call it when your plans are written; the opening scene then opens.',args:{summary:{type:'string',desc:'One line of what you prepared (DM log only)',optional:true}}},
  // Deferred actions and chosen wakes (issue #635, game side src/sim/dmwhen.js): act between your turns, on time.
  {name:'when',act:true,desc:'Leave an action behind that fires when a trigger trips, between your turns: "when the Fellowship enters Mirefen, narrate the fog", "at dusk the hermit says ...", "when Kerin talks to Mara, whisper ...". trigger (one of the list) with on (its arguments: region, town, place, npc, hero, company, radius, pct, name, quest, scene, hh, h, level as the trigger needs; company or hero narrows who trips it, default any agent hero); action: narrate, npc_say, whisper, dream, stage_scene, post_hook, place_person, mark_place, give_item, take_item, pull_lever, or a lever name such as set_condition or set_attitude; args: that tool\'s arguments as you would call it ("{who}" in a text or near is the hero who tripped it). Checked when set (a staged scene is previewed) and run when it fires through the same tool, so the day\'s caps, lever limits, the Fellowship reserve and every refusal apply then; a refused one is logged and dropped. Triggers are edges: what is already true does not fire until it happens again. hours 1-72 (default 24) until it lapses; once yes (default) or no (then at most once a game day). At most 6 pending, 12 set a game day. Every firing is a DM log line and a dm_status fired item.',
    args:{trigger:{type:'string',enum:TRIGGER_NAMES,desc:'What trips it: enter_region {region}, enter_town {town}, near_place {place, radius?}, near_person {npc, radius?}, talks_to {npc}, member_hp_below {pct}, foe_dies {name}, quest_scene {quest, scene}, camp_made, night_falls (20:00), day_breaks (06:00), at_time {hh}, after_hours {h}, hero_levels {level?}, oath_kept; company? or hero? narrows the hero triggers'},
      on:{type:'object',desc:'The trigger\'s arguments, e.g. {"region":"Mirefen","company":"fellowship"}',optional:true},
      action:{type:'string',desc:'The tool it runs (narrate, npc_say, whisper, dream, stage_scene, post_hook, place_person, mark_place, give_item, take_item, summon_hero, pull_lever) or a lever name'},
      args:{type:'object',desc:'The action\'s arguments, as you would call that tool now, e.g. {"text":"...","near":"{who}"}; for a lever name, its params'},
      hours:{type:'number',desc:'Game hours until it lapses unfired (1-72, default 24)',optional:true},once:{type:'string',enum:['yes','no'],desc:'yes (default): fires once; no: again on each new trip, at most once a game day',optional:true},
      reason:{type:'string',desc:'Why, in one sentence (DM log only; also the reason of a lever it pulls)'}}},
  {name:'whens',act:false,desc:'Your pending whens and watches (id, trigger, action, hours left), what fired in the last game day (fired, watches_fired), the trigger list with arguments and the actions a when may carry.',args:{}},
  {name:'unwhen',act:true,desc:'Cancel a pending when by id (whens lists them).',args:{id:{type:'integer',desc:'The when id'}}},
  {name:'watch',act:true,desc:'Choose what wakes you: the same triggers as when, but a trip starts your next turn early (an event turn, within the day\'s event turns and their spacing) and the turn prompt names it, e.g. watch {trigger:"enter_region", on:{"region":"Mirefen","company":"fellowship"}, note:"the bog witch waits there"}. Beside the evening turn and the Fellowship\'s own changes. At most 6 set, 12 a game day; hours 1-72 (default 24); once yes (default) or no.',
    args:{trigger:{type:'string',enum:TRIGGER_NAMES,desc:'What wakes you (the when triggers)'},on:{type:'object',desc:'The trigger\'s arguments, as for when',optional:true},
      note:{type:'string',desc:'What to remember when it wakes you (max 200)',optional:true},hours:{type:'number',desc:'Game hours it stays set (1-72, default 24)',optional:true},
      once:{type:'string',enum:['yes','no'],desc:'yes (default) or no (again on each new trip, at most once a game day)',optional:true}}},
  {name:'watches',act:false,desc:'The same list as whens: your watches and whens, and what tripped in the last game day.',args:{}},
  {name:'unwatch',act:true,desc:'Drop a watch by id (whens or watches lists them).',args:{id:{type:'integer',desc:'The watch id'}}},
  {name:'companion_call',act:false,desc:'A scripted companion who rides with an agent company (a hire, a companion who answered an invite) waits for your voice: its card (class, home, traits, oath, how it rides), where, what its company did today, the last lines it heard, what it already said to each listener, the words of the hero it answers, and the seconds left. Answer with companion_say; silence is filled from its usual talk.',args:{budget_s:{type:'number',desc:'Real seconds your voice needs per answer (4-30, default 8): the game waits that long while you poll',optional:true},wait_ms:{type:'integer',desc:'For a voice loop: hold the request until a call waits, up to this many real ms (0-25000; default 0 answers at once). The answer time counts from when you first read the call',optional:true}}},
  {name:'companion_say',act:true,desc:'Speak as the waiting companion (companion_call): one or two sentences in their own voice, true to their card and the day, new to whoever hears it (a line it already said to them is refused). Never words for a hero: a quote put in the mouth of a hero is cut. 6 lines a companion a game day.',args:{call:{type:'integer',desc:'The call id from companion_call'},text:{type:'string',desc:'What the companion says (up to 300 characters)'}}},
  {name:'log_intent',act:true,desc:'Write one line of your reasoning or plan into the DM log (max 200 characters, a few a day), so the watcher can follow what you are preparing.',args:{text:{type:'string',desc:'The line'}}},
  {name:'wish',act:false,desc:'Leave a note for the people who build the game about a tool you wished you had, to tell this story. It is read later and never answered in play; nothing changes this session, and you may wish for things the rules forbid (touching HP, life, levels, time). 3 a game day, so pick the ones that mattered. English only.',args:{tool:{type:'string',desc:'The name you would give it (2-32 characters, snake_case suggested)'},what:{type:'string',desc:'What it would have done (up to 300 characters)'},why:{type:'string',desc:'Why this moment needed it (up to 200)'},moment:{type:'string',desc:'The moment itself, a sentence of story (up to 200)'}}},
];
export const DM_TOOL_NAMES=DM_TOOLS.map(t=>t.name);
